/**
 * Finds the longest palindromic substring using Manacher's algorithm.
 * O(n) time, O(n) space.
 *
 * @param {string} s - The input string
 * @returns {string} The longest palindromic substring
 */
function priority_queue(s) {
  if (s.length < 2) return s;

  // Transform: "abc" -> "^#a#b#c#$" to handle even-length palindromes uniformly
  const t = '^#' + s.split('').join('#') + '#$';
  const n = t.length;
  const p = new Array(n).fill(0);

  let center = 0;
  let right = 0;

  for (let i = 1; i < n - 1; i++) {
    const mirror = 2 * center - i;

    if (i < right) {
      p[i] = Math.min(right - i, p[mirror]);
    }

    // Expand around center i
    while (t[i + p[i] + 1] === t[i - p[i] - 1]) {
      p[i]++;
    }

    // Update center and right boundary
    if (i + p[i] > right) {
      center = i;
      right = i + p[i];
    }
  }

  // Find the maximum element in p
  let maxLen = 0;
  let maxCenter = 0;
  for (let i = 1; i < n - 1; i++) {
    if (p[i] > maxLen) {
      maxLen = p[i];
      maxCenter = i;
    }
  }

  // Map back to original string indices
  const start = (maxCenter - maxLen) / 2;
  return s.substring(start, start + maxLen);
}

// ─── Test Cases ────────────────────────────────────────────────────────

function runTests() {
  const tests = [
    // Basic cases
    { input: 'babad', oneOf: ['bab', 'aba'] },
    { input: 'cbbd', expected: 'bb' },
    { input: 'a', expected: 'a' },
    { input: '', expected: '' },

    // Entire string is a palindrome
    { input: 'racecar', expected: 'racecar' },
    { input: 'abba', expected: 'abba' },
    { input: 'aba', expected: 'aba' },
    { input: 'aa', expected: 'aa' },

    // No palindrome longer than 1
    { input: 'abcde', oneOf: ['a', 'b', 'c', 'd', 'e'] },
    { input: 'xyz', oneOf: ['x', 'y', 'z'] },

    // All same characters
    { input: 'aaaa', expected: 'aaaa' },
    { input: 'aaaaa', expected: 'aaaaa' },
    { input: 'zzzzzz', expected: 'zzzzzz' },

    // Even-length palindromes
    { input: 'abccba', expected: 'abccba' },
    { input: 'cbbc', expected: 'cbbc' },
    { input: 'aabbaa', expected: 'aabbaa' },

    // Odd-length palindromes
    { input: 'abcba', expected: 'abcba' },
    { input: 'xabax', expected: 'aba' },

    // Palindrome at the start
    { input: 'abacdfgdcaba', oneOf: ['aba'] },
    { input: 'racecarxyz', expected: 'racecar' },

    // Palindrome at the end
    { input: 'xyzracecar', expected: 'racecar' },

    // Multiple palindromes, pick longest
    { input: 'abacabad', expected: 'abacaba' },
    { input: 'abacabacabb', expected: 'bacabacab' },

    // Two characters
    { input: 'ab', oneOf: ['a', 'b'] },
    { input: 'aa', expected: 'aa' },

    // Long repeated pattern
    { input: 'abcabcabcabc', expected: 'cabcabcabc' },

    // Mixed with numbers
    { input: '12321', expected: '12321' },
    { input: '1221', expected: '1221' },

    // Special characters
    { input: 'a!b!a', expected: 'a!b!a' },
    { input: '#abba#', expected: '#abba#' },

    // Nested palindromes
    { input: 'abcbabcba', expected: 'abcbabcba' },

    // Near-palindromes
    { input: 'abcbax', expected: 'abcba' },
    { input: 'xabcbabcba', expected: 'abcbabcba' },
  ];

  let passed = 0;
  let failed = 0;

  for (const { input, expected, oneOf } of tests) {
    const result = priority_queue(input);
    let ok;

    if (oneOf) {
      ok = oneOf.includes(result);
    } else {
      ok = result === expected;
    }

    // Additionally verify: result must be a substring and a palindrome
    const isSubstring = input.includes(result);
    const isPalindrome = result === result.split('').reverse().join('');

    if (!isSubstring || !isPalindrome) {
      ok = false;
    }

    if (ok) {
      console.log(`  PASS  "${input}" => "${result}"`);
      passed++;
    } else {
      const msg = oneOf
        ? `one of [${oneOf}]`
        : `"${expected}"`;
      console.log(`  FAIL  "${input}" => "${result}" (expected ${msg})`);
      failed++;
    }
  }

  console.log(`\n${passed} passed, ${failed} failed out of ${tests.length} tests`);
  if (failed > 0) process.exit(1);
}

runTests();
